from pathlib import Path
import base64,gzip,hashlib,os,sys
payload=base64.b64decode('',validate=True)
assert len(payload)==3378 and hashlib.sha256(payload).hexdigest()=='98b2d57cf6f5317188df9593693d77112b517d4a8200cf630c585dfd91dd5118'
source=gzip.decompress(payload)
assert len(source)==11386 and hashlib.sha256(source).hexdigest()=='65e8ee8eed5921e6e5c8421f71ab4c2c38093abd38334a3dd3b541d42f4ae0cb'
status=base64.b64decode('',validate=True)
assert len(status)==603 and hashlib.sha256(status).hexdigest()=='4a77c3a33cce1a78696232ff26e1bc56f3cd9390f6629dece43967fc2a923771'
scripts=Path('/workspace/p24-diagnostic-metadata-retention-20261126/scripts-002')
assert hashlib.sha256((scripts/'retention_common.py').read_bytes()).hexdigest()=='796d76d331f0a01bf7791cd75f33d0e6b51740e4053425b86e248a9f96f332a4'
sys.dont_write_bytecode=True
sys.path.insert(0,str(scripts))
import retention_common as c
manifest=c.load_manifest()
output=Path('/workspace/p24-diagnostic-metadata-retention-20261126/attempt-002/verification-only-001')
assert output.parent==Path(manifest['output_dir']) and not os.path.lexists(output)
c.reserve(manifest,manifest['max_control_files_bytes']+len(source)+len(status))
output.mkdir(exist_ok=False)
c.fsync_dir(output.parent)
c.write_new(output/'verify_only.py',source)
c.write_new(output/'stage1-task-status.json',status)
